#include "rinkfit/joint_source_guard.hpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc==2&&std::string(argv[1])=="--capabilities"){std::cout<<R"({"schema":"rinkfit.joint_backend_capabilities.v1","joint_model":"rinkfit.joint_event_model.v1","joint_packet":"rinkfit.joint_packet.v1","engineering_recovery_native_pixel_v1":true,"shared_scene":true,"dynamic_rigs_shots":true,"Jet_global32_assembly":true,"full_correlated_W":true,"ordinary_station_joint_optimization":true,"exact_local_RS_query_derivatives":true,"formal_Phase_I_II_driver":true,"formal_original_domain_stationarity_requires_chart_witness_decode":true,"whole_RS_certificate_requires_independent_replay":true})";return 0;}if(argc==5&&std::string(argv[1])=="--qualification-check"){auto m=rinkfit::JointEventModel::load(argv[2]);auto p=rinkfit::JointPacket::load(argv[3],m);rinkfit::assert_joint_board_source_qualification(p,argv[3]);const auto recalled=rinkfit::joint_source_recall_marker(p.source_json,argv[3],true);if(!recalled.empty())throw std::runtime_error("source qualification recalled: "+recalled.string());std::size_t active=0,rank=0;for(const auto&r:p.rows)active+=r.active;for(const auto&g:p.groups)rank+=g.rank;rinkfit::eventio::atomic_json(argv[4],{{"passed",true},{"source_packet_sha256",p.source_hash},{"raw_rows",p.rows.size()},{"active_rows",active},{"statistical_rank",rank},{"shots",m.shots.size()},{"rigs",m.rigs.size()}});return 0;}if(argc>=5&&std::string(argv[1])=="--engineering-recovery")return rinkfit::run_joint_engineering_recovery(argv[2],argv[3],argv[4],argc>5?argv[5]:"");if(argc>=5&&(std::string(argv[1])=="--formal"||std::string(argv[1])=="--formal-audit"||std::string(argv[1])=="--geometry-phr"))return rinkfit::run_joint_formal(argv[2],argv[3],argv[4],argc>5?argv[5]:"",std::string(argv[1])=="--formal-audit",std::string(argv[1])=="--geometry-phr");if(argc==5&&std::string(argv[1])=="--verify"){auto m=rinkfit::JointEventModel::load(argv[2]);auto p=rinkfit::JointPacket::load(argv[3],m);rinkfit::JointProblemBuilder b(std::move(m),std::move(p));auto j=rinkfit::verify_joint_kernel(b);std::ofstream f(argv[4]);f<<j.dump(2);std::cout<<j.dump(2);return 0;}if(argc<4)throw std::runtime_error("usage: joint_fit MODEL PACKET OUT [ITERATIONS] [THREADS]");auto model=rinkfit::JointEventModel::load(argv[1]);auto packet=rinkfit::JointPacket::load(argv[2],model);rinkfit::JointProblemBuilder b(std::move(model),std::move(packet));rinkfit::eventio::Json stage=rinkfit::eventio::Json::object();if(argc>6){stage=rinkfit::eventio::read_json(argv[6]);b.observed_row_time_new_sources=stage.value("observed_row_time_new_sources",false);if(b.observed_row_time_new_sources&&!b.packet.source_json.contains("new_source_start"))throw std::runtime_error("source row time initialization requires immutable new_source_start");for(auto&block:b.model.blocks)for(const auto&prefix:stage.value("fix_prefixes",std::vector<std::string>{}))if(block.name.rfind(prefix,0)==0)block.constant=true;for(const auto&sid:stage.value("fix_shot_nuisance",std::vector<std::string>{}))b.fixed_nuisance_shots.insert(sid);}if((argc>4&&std::stoi(argv[4])>0)||stage.value("recapture_new_sources",false)){rinkfit::assert_joint_board_source_qualification(b.packet,argv[2]);auto marker=rinkfit::joint_source_recall_marker(b.packet.source_json,argv[2],true);if(!marker.empty())throw std::runtime_error("source physical identity certificate recalled: "+marker.string()+"; "+rinkfit::eventio::read_json(marker.string()).dump());}std::filesystem::path out=argv[3];if(std::filesystem::exists(out))throw std::runtime_error("immutable joint generation output must not exist");std::filesystem::create_directories(out);int it=argc>4?std::stoi(argv[4]):0;if(stage.value("recapture_new_sources",false)){auto receipt=rinkfit::recapture_joint_initial_nuisance(b,out);if(receipt.at("invalid_rows")!=0)throw std::runtime_error("new-source finite RS capture failed; see per-row source diagnosis");}auto before=b.replay(out/"before");if(before.at("invalid_rows")!=0&&!b.observed_row_time_new_sources)throw std::runtime_error("joint initial state has invalid active rows; see before/value_report.json");if(b.observed_row_time_new_sources){std::size_t count=0;for(std::size_t i=0;i<b.packet.source_json.at("new_source_start").get<std::size_t>();++i)count+=b.packet.rows[i].active?1:0;if(before.at("shot_metrics").at("s01").at("valid_rows")!=count)throw std::runtime_error("observed-row-time initializer may never bypass original s01 invalid replay");}if(it){auto attempt=b.solve(it,argc>5?std::stoi(argv[5]):8);attempt["temporary_initialization_fixing"]=stage;std::ofstream f(out/"solver_attempt.json");f<<attempt.dump(2);}auto report=b.replay(out/"state");std::cout<<report.dump(2)<<std::endl;return report.at("invalid_rows")==0?0:2;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
